UPDATE socialapp.t_users u
   SET banned_until = b.until
  FROM (SELECT user_id, MAX(banned_until) AS until
          FROM socialapp.t_user_bans
         WHERE banned_until > now()
         GROUP BY user_id) b
 WHERE b.user_id = u.id;

